void launch_a16(const Tensor& x, const Weight& w, Tensor& y, cudaStream_t stream) {
    select_a16(x.ne[1])(x, w, y, stream);
}

using T16R64  = Nvfp4A4MmaSchedule<16, 64, 256, 1, 4, 2, 2>;
using T32R64  = Nvfp4A4MmaSchedule<32, 64, 256, 2, 4, 2, 2>;
using T64R64  = Nvfp4A4MmaSchedule<64, 64, 256, 2, 4, 2, 1>;
using T128R128Pipelined = Nvfp4A4MmaSchedule<128, 128, 256, 4, 2, 2, 1>;

Nvfp4A4Route select_a4(std::int32_t tokens) {
    // GB10 2026-11-03: the prefill token tile is now picked per width by the 48-SM wave-fill rule
    // (nvfp4_a4_tma_prefill_route). Measured here: T = 257-384 runs 6.4-7.8% ahead on the
    // 128-token tile and 640 by 1.2%; from 768 up the 23.6 MB weight matrix is re-read once per
    // extra token tile and the narrow tile measures up to 1.3% behind.
    if (tokens >= 257) return nvfp4_a4_tma_prefill_route<Geometry>(tokens);
    if (tokens >= 129) return nvfp4_a4_tma_route<Nvfp4ScaleLayout::Tiled128>();
    if (tokens <= 16) return nvfp4_a4_mma_route<Geometry, T16R64>();
    if (tokens <= 32) return nvfp4_a4_mma_route<Geometry, T32R64>();
    if (tokens <= 64) return nvfp4_a4_mma_route<Geometry, T64R64>();
    return nvfp4_a4_mma_route<Geometry, T128R128Pipelined>();
}

// GB10 2026-10-31 (T5): the A4 admission starts at the 2-term/prefill width, not at 33. Measured
// on the public route (cold 32 MiB L2, 25 repeats, minimum), the 1-term A4 ladder this shape
// registers is 7..11% SLOWER than the A16 table across the MTP-verification widths -- T = 33:
// 136.26us against 124.61us (73.8% against 80.6% of the 246 GB/s READ reference), T = 48: 136.74
// against 123.74 (75.0% against 82.9%), T = 64: 136.26 against 126.91 (76.9% against 82.6%) --
// and 25..37% faster from T = 65, where it wins outright (T = 65: 111.52us against 148.10, 94.1%
// against 70.9%; T = 128: 114.11 against 181.86, 99.6% against 62.5%). select_a4 keeps its
// T <= 64 rungs so a future gate change has its measured per-width argmin recorded.
bool uses_a4(std::int32_t, std::int32_t max_tokens) { return max_tokens >= 33; }
